#!/usr/bin/env python3
"""Monthly long-history allocation table, January 2000 onward.

Generates one observation per calendar month using the first available NIFTY 50
trading day of that month, while displaying the date as the first calendar day.
Public output columns are: Date, NIFTY 50, RBI Repo Rate %, Equity %, Debt %.

For a genuinely continuous 2000-present reconstruction, this study uses only
the valuation lenses that exist across the full history: P/E (30%),
profitability-adjusted P/B (25%) and dividend yield (10%), renormalised across
those 65 weight points. The live V3.6 allocation curve itself remains unchanged
(k=1.35, zc=2.5). The India-yield lens, earnings overlay and macro overlay are
excluded for the ENTIRE backtest rather than being silently neutral-filled or
switched on part-way through history.

Pre-31-Mar-2021 NSE index P/E history used the older standalone-earnings
methodology, while the current index P/E uses consolidated trailing financials
where available. Thus the pre-2021 rows are a mechanical historical sensitivity
series, not directly methodology-comparable to current V3.6 readings.

RBI rate convention: the repo/policy rate in force on the displayed calendar
first day. Before the June-2000 LAF series, the then fixed repo rate is used.
RBI/Reuters note that before 29-Oct-2004 the repo/reverse-repo nomenclature was
opposite to current international usage; the historical policy-rate series is
kept on the current-comparable convention used by RBI/Reuters timelines.
"""
from __future__ import annotations
from datetime import date
from pathlib import Path
import json, math
import pandas as pd
import update_data as b

ROOT=Path(__file__).resolve().parents[1]
CSV_OUT=ROOT/'data'/'backtest_monthly_2000.csv'
JSON_OUT=ROOT/'data'/'backtest_monthly_2000.json'
START=date(2000,1,1)
LIVE_K=1.35
LIVE_ZC=2.5
C={'peM':22.44,'peS':2.08,'pbM':3.88,'pbS':.45,'roeM':17.36,'roeS':1.92,
   'dyM':1.25,'dyS':.18,'beta':.60}

# Effective-date history of the RBI repo/policy rate. June-2000 onward follows
# the RBI/Reuters historical policy-rate timeline. Jan-May 2000 uses the fixed
# repo rate then in force (6%, cut to 5% effective 03-Apr-2000).
REPO_CHANGES=[
 ('1999-03-01',6.00),('2000-04-03',5.00),('2000-06-05',9.05),('2000-06-07',9.00),('2000-06-09',9.05),('2000-06-12',9.25),('2000-06-13',9.55),('2000-06-14',10.85),('2000-06-19',13.50),('2000-06-20',14.00),('2000-06-21',13.50),('2000-06-22',13.00),('2000-06-23',13.05),('2000-06-27',12.60),('2000-06-28',12.25),('2000-07-13',9.00),('2000-07-21',10.00),('2000-08-09',16.00),('2000-08-30',15.00),('2000-09-06',13.50),('2000-10-13',10.25),('2000-11-06',10.00),
 ('2001-03-09',9.00),('2001-04-30',8.75),('2001-06-07',8.50),('2002-03-28',8.00),('2002-11-12',7.50),('2003-03-07',7.10),('2003-03-19',7.00),('2004-03-31',6.00),('2005-10-26',6.25),('2006-01-24',6.50),('2006-06-08',6.75),('2006-07-25',7.00),('2006-10-30',7.25),('2007-01-31',7.50),('2007-03-30',7.75),('2008-06-11',8.00),('2008-06-24',8.50),('2008-07-29',9.00),('2008-10-20',8.00),('2008-11-03',7.50),('2008-12-08',6.50),('2009-01-02',5.50),('2009-03-04',5.00),('2009-04-21',4.75),
 ('2010-03-19',5.00),('2010-04-20',5.25),('2010-07-02',5.50),('2010-07-27',5.75),('2010-09-16',6.00),('2010-11-02',6.25),('2011-01-25',6.50),('2011-03-17',6.75),('2011-05-03',7.25),('2011-06-16',7.50),('2011-07-26',8.00),('2011-09-16',8.25),('2011-10-25',8.50),('2012-04-17',8.00),('2013-01-29',7.75),('2013-03-19',7.50),('2013-05-03',7.25),('2013-09-20',7.50),('2013-10-29',7.75),('2014-01-28',8.00),('2015-01-15',7.75),('2015-03-04',7.50),('2015-06-02',7.25),('2015-09-29',6.75),('2016-04-05',6.50),('2016-10-04',6.25),('2017-08-02',6.00),('2018-06-06',6.25),('2018-08-01',6.50),('2019-02-07',6.25),('2019-04-04',6.00),('2019-06-06',5.75),('2019-08-07',5.40),('2019-10-04',5.15),('2020-03-27',4.40),('2020-05-22',4.00),('2022-05-04',4.40),('2022-06-08',4.90),('2022-08-05',5.40),('2022-09-30',5.90),('2022-12-07',6.25),('2023-02-08',6.50),('2025-02-07',6.25),('2025-04-09',6.00),('2025-06-06',5.50),('2025-12-05',5.25)
]
REPO_CHANGES=[(pd.Timestamp(d),float(r)) for d,r in REPO_CHANGES]


def finite(x):
    try:return x is not None and math.isfinite(float(x))
    except (TypeError,ValueError):return False

def clip(x,a,b):return max(a,min(b,float(x)))
def curve(z,k=LIVE_K,zc=LIVE_ZC):
    f=lambda x:100/(1+math.exp(float(k)*x));lo=f(zc);hi=f(-zc)
    return clip((f(float(z))-lo)/(hi-lo)*100,0,100)

def valuation_z(pe,pb,dy):
    pe,pb,dy=map(float,(pe,pb,dy));roe=100*pb/pe
    lenses=[
      ((pe-C['peM'])/C['peS'],30),
      ((pb-C['pbM'])/C['pbS']-C['beta']*(roe-C['roeM'])/C['roeS'],25),
      (-(dy-C['dyM'])/C['dyS'],10),
    ]
    return sum(v*w for v,w in lenses)/sum(w for _,w in lenses)

def repo_on(dt):
    dt=pd.Timestamp(dt);eligible=[r for d,r in REPO_CHANGES if d<=dt]
    return eligible[-1] if eligible else None

def fetch_ratio_first_days():
    from jugaad_data.nse import index_pe_raw
    end=date.today();rows=index_pe_raw('NIFTY 50',START,end)
    parsed=[]
    for x in rows or []:
        dt=b.pdate(b.pick(x,['Date','DATE','HistoricalDate']))
        pe=b.fnum(b.pick(x,['P/E','PE','pe']));pb=b.fnum(b.pick(x,['P/B','PB','pb']));dy=b.fnum(b.pick(x,['Div Yield %','Div Yield','Dividend Yield','DY','divYield']))
        if dt and START<=dt<=end and all(finite(v) and float(v)>0 for v in (pe,pb,dy)):
            parsed.append((pd.Timestamp(dt),float(pe),float(pb),float(dy)))
    if not parsed:raise RuntimeError('No NIFTY 50 valuation history returned')
    q=pd.DataFrame(parsed,columns=['trading_date','pe','pb','dy']).drop_duplicates('trading_date').sort_values('trading_date')
    q['month']=q.trading_date.dt.to_period('M')
    return q.groupby('month',as_index=False).first()

def fetch_nifty_first_days():
    from jugaad_data.nse import index_raw
    end=date.today();rows=index_raw('NIFTY 50',START,end)
    parsed=[]
    for x in rows or []:
        dt=b.pdate(b.pick(x,['Date','DATE','HistoricalDate','Index Date']))
        level=b.fnum(b.pick(x,['CLOSE','Close','Closing Index Value','Index Value','INDEX_VALUE','close']))
        if dt and START<=dt<=end and finite(level) and float(level)>0:parsed.append((pd.Timestamp(dt),float(level)))
    if not parsed:raise RuntimeError('No NIFTY 50 price history returned')
    q=pd.DataFrame(parsed,columns=['market_date','nifty50']).drop_duplicates('market_date').sort_values('market_date');q['month']=q.market_date.dt.to_period('M')
    return q.groupby('month',as_index=False).first()

def build():
    ratios=fetch_ratio_first_days();prices=fetch_nifty_first_days();q=ratios.merge(prices,on='month',how='left');rows=[]
    for _,r in q.iterrows():
        month=r['month'];z=valuation_z(r.pe,r.pb,r.dy);equity=curve(z);eq_int=max(0,min(100,int(round(equity))));cal_date=month.start_time
        rows.append({'Date':str(cal_date.date()),'NIFTY 50':round(float(r.nifty50),2) if finite(r.nifty50) else None,'RBI Repo Rate %':repo_on(cal_date),'Equity %':eq_int,'Debt %':100-eq_int})
    if not rows:raise RuntimeError('No complete monthly NIFTY valuation observations')
    public=pd.DataFrame(rows)
    expected=pd.period_range('2000-01',pd.Period(date.today(),freq='M'),freq='M');observed=pd.PeriodIndex(pd.to_datetime(public['Date']).dt.to_period('M'));missing=[str(x) for x in expected if x not in observed]
    if public['NIFTY 50'].isna().any():raise RuntimeError('Missing NIFTY 50 level for one or more months')
    public.to_csv(CSV_OUT,index=False)
    meta={'status':'complete' if not missing else 'partial','model_version':'3.6-long-history-common-lens','scope':'common-factor valuation backtest only; P/E + profitability-adjusted P/B + dividend yield. Yield-gap, earnings and macro overlays excluded for the entire 2000-present series.','start':public.Date.iloc[0],'end':public.Date.iloc[-1],'rows':int(len(public)),'missing_months':missing,'signal_rule':'first available NIFTY 50 trading day in each calendar month; displayed Date is the calendar month first day','nifty_column_rule':'NIFTY 50 close on the first available trading day of each month','rbi_rate_rule':'RBI repo/policy rate in force on the displayed calendar first day; Jan-May 2000 uses the fixed repo rate then in force','factor_weights':{'pe':30,'profitability_adjusted_pb':25,'dividend_yield':10},'live_curve_parameters':{'curve_slope_k':LIVE_K,'extreme_threshold_zc':LIVE_ZC},'reference_constants':C,'methodology_warning':'Pre-31-Mar-2021 NIFTY P/E history used the older standalone-earnings methodology; current methodology uses consolidated trailing earnings where available. Pre-2021 rows are therefore a mechanical sensitivity series, not directly comparable to current V3.6 valuation levels.','repo_nomenclature_warning':'Before 29-Oct-2004 RBI repo/reverse-repo nomenclature was opposite to current international usage; historical policy-rate values use the current-comparable RBI/Reuters convention.','rows_data':public.to_dict(orient='records')}
    JSON_OUT.write_text(json.dumps(meta,indent=2,allow_nan=False),encoding='utf-8');return meta

if __name__=='__main__':
    try:
        x=build();print(json.dumps({'status':x['status'],'rows':x['rows'],'start':x['start'],'end':x['end'],'missing_months':x['missing_months']}))
    except Exception as e:
        error={'status':'unavailable','error':f'{type(e).__name__}: {e}'};JSON_OUT.write_text(json.dumps(error,indent=2),encoding='utf-8');print(json.dumps(error));raise

pipeline_sources.scripts/current_definition_reconstructio:
#!/usr/bin/env python3
"""Current-definition NIFTY 50 reconstruction feasibility and coverage audit.

Research only. This module does NOT modify model.js, multiasset.py, latest.json,
or any prospective archived decision.

Goal
----
Reconstruct historical NIFTY 50 valuation ratios using:
  * the actual historical NIFTY constituent weights in force at each date; and
  * today's accounting definitions for index P/E, P/B and dividend yield;
  * only company information that had been filed/announced by the signal date.

This is intentionally different from a counterfactual "free-float NIFTY since
2000". NIFTY changed to free-float weighting only in June 2009. The research
question here is the effect of today's *accounting definitions*, so historical
index weights are preserved as actually published.

The module has two roles:
1) exact deterministic aggregation/point-in-time eligibility primitives that
   future reconstruction rows must satisfy; and
2) a public-source coverage audit that refuses to manufacture missing history.

A month is not labelled reconstructable until all required constituent fields
pass point-in-time and weight-completeness checks.
"""
from __future__ import annotations

from datetime import date, datetime, timezone
from io import BytesIO, StringIO
from pathlib import Path
import json
import math
import re
import zipfile

import pandas as pd
import requests

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "data" / "current_definition_reconstruction.json"

UA = {
    "User-Agent": (
        "Mozilla/5.0 (compatible; AnupNiftyValuation/3.6; "
        "personal non-commercial research)"
    )
}

# Official definition / source inventory. These are recorded as evidence, not
# treated as proof that every historical observation is already machine-readable.
OFFICIAL_SOURCES = {
    "current_pe_definition": {
        "url": "https://www.niftyindices.com/resources/index-concepts/price-earnings-ratio",
        "rule": (
            "Index market capitalisation divided by index earnings; constituent "
            "earnings use trailing four quarters consolidated financials where "
            "available, with standalone fallback where consolidated results are unavailable."
        ),
    },
    "current_pb_definition": {
        "url": "https://www.niftyindices.com/resources/index-concepts/price-to-book-value",
        "rule": (
            "Index market capitalisation divided by index book value; consolidated "
            "net worth is used where available, with standalone fallback."
        ),
    },
    "current_dy_definition": {
        "url": "https://www.niftyindices.com/resources/index-concepts/dividend-yield",
        "rule": "Rolling twelve-month equity dividends based on ex-dividend date divided by market capitalisation.",
    },
    "weight_archive_monthly": {
        "url": "https://www.niftyindices.com/reports/monthly-reports",
        "rule": "Official monthly reports include Indices Market Capitalisation & Weightage archives.",
    },
    "ismr_2001": {
        "url": "https://nsearchives.nseindia.com/web/sites/default/files/inline-files/ismr.pdf",
        "rule": (
            "NSE Indian Securities Market Review 2001, Annexure 4.2, publishes "
            "monthly S&P CNX Nifty security weights from Apr-2000 through Jun-2001."
        ),
    },
    "financial_results": {
        "url": "https://www.nseindia.com/companies-listing/corporate-filings-financial-results",
        "api": "https://www.nseindia.com/api/corporates-financial-results",
        "rule": "NSE corporate financial-result filings; XBRL links are used where supplied.",
    },
    "corporate_actions": {
        "url": "https://www.nseindia.com/companies-listing/corporate-filings-actions",
        "api": "https://www.nseindia.com/api/corporates-corporateActions",
        "rule": "NSE corporate actions, including dividend ex-dates and share splits/bonuses.",
    },
}

# Verified chronology from official NSE/Nifty methodology publications.
METHODOLOGY = {
    "weighting": {
        "pre_2009_06_26": "actual historical NIFTY weighting then in force",
        "from_2009_06_26": "free-float market-capitalisation weighting",
        "source": "https://www.nseindia.com/products-services/indices-nifty50-index",
    },
    "accounting_target": {
        "pe": "trailing-four-quarter consolidated earnings, standalone fallback",
        "pb": "consolidated net worth from latest eligible annual financials, standalone fallback",
        "dy": "rolling-12-month equity dividends by ex-dividend date",
    },
}

# The later monthly-archive filename pattern is public on the Nifty Indices
# archive UI. We probe representative months only; lack of access in CI is a
# network result, not evidence that the archive itself does not exist.
WEIGHT_ARCHIVE_PROBES = [
    ("2013-09", "https://www.niftyindices.com/Indices_-_Market_Capitalisation_and_Weightage/indices_dataSep2013.zip"),
    ("2015-01", "https://www.niftyindices.com/Indices_-_Market_Capitalisation_and_Weightage/indices_dataJan2015.zip"),
    ("2020-01", "https://www.niftyindices.com/Indices_-_Market_Capitalisation_and_Weightage/indices_dataJan2020.zip"),
    ("2023-09", "https://www.niftyindices.com/Indices_-_Market_Capitalisation_and_Weightage/indices_dataSep2023.zip"),
]

# Representative companies chosen to exercise banking, IT, energy, consumer,
# industrial and financial statement templates. This is a source-coverage probe,
# not a claim of full index reconstruction.
FINANCIAL_PROBE_SYMBOLS = [
    "RELIANCE",
    "HDFCBANK",
    "ICICIBANK",
    "TCS",
    "INFY",
    "ITC",
    "LT",
    "SBIN",
]


def finite(x):
    try:
        return x is not None and math.isfinite(float(x))
    except (TypeError, ValueError):
        return False


def normalize_weights(weights, tolerance=0.015):
    """Return normalised decimal weights, rejecting incomplete snapshots.

    Published monthly tables may sum to 99.99/100.01 because of display
    rounding. Materially incomplete snapshots are rejected rather than silently
    renormalised.
    """
    s = pd.Series(weights, dtype="float64")
    if s.empty or s.isna().any() or (s < 0).any():
        raise ValueError("weights must be complete, finite and non-negative")
    total = float(s.sum())
    if not math.isfinite(total) or total <= 0:
        raise ValueError("invalid weight total")
    # Accept either decimal or percentage input.
    if total > 2.0:
        s = s / 100.0
        total = float(s.sum())
    if abs(total - 1.0) > float(tolerance):
        raise ValueError(f"incomplete index weights: sum={total:.6f}")
    return s / total


def aggregate_current_definition(weights, pe, pb, dividend_yield_pct):
    """Aggregate constituent ratios using exact index weights.

    Algebra:
      PE_index = 1 / sum(w_i / PE_i)
      PB_index = 1 / sum(w_i / PB_i)
      DY_index = sum(w_i * DY_i)

    Therefore exact historical IWFs are not separately required once the actual
    historical index weights are known. IWF/capping effects are already embedded
    in those published weights.
    """
    w = normalize_weights(weights)
    pe = pd.Series(pe, dtype="float64")
    pb = pd.Series(pb, dtype="float64")
    dy = pd.Series(dividend_yield_pct, dtype="float64")
    if not (len(w) == len(pe) == len(pb) == len(dy)):
        raise ValueError("constituent arrays must have identical length")
    if pe.isna().any() or pb.isna().any() or dy.isna().any():
        raise ValueError("missing constituent valuation field")
    if (pe <= 0).any() or (pb <= 0).any() or (dy < 0).any():
        raise ValueError("invalid constituent valuation field")
    pe_den = float((w / pe).sum())
    pb_den = float((w / pb).sum())
    if pe_den <= 0 or pb_den <= 0:
        raise ValueError("invalid aggregate denominator")
    return {
        "pe": 1.0 / pe_den,
        "pb": 1.0 / pb_den,
        "dividend_yield_pct": float((w * dy).sum()),
    }


def point_in_time_eligible(filing_or_announcement_time, signal_time):
    """True only when the information was public no later than the signal."""
    a = pd.Timestamp(filing_or_announcement_time)
    s = pd.Timestamp(signal_time)
    if a.tzinfo is not None:
        a = a.tz_convert(None)
    if s.tzinfo is not None:
        s = s.tz_convert(None)
    return bool(a <= s)


def current_definition_company_inputs(
    *, market_cap, ttm_earnings, book_value, rolling_12m_dividends
):
    """Convert point-in-time accounting numerators to company valuation ratios."""
    vals = [market_cap, ttm_earnings, book_value, rolling_12m_dividends]
    if not all(finite(x) for x in vals):
        raise ValueError("all company inputs must be finite")
    mc, earn, book, divs = map(float, vals)
    if mc <= 0 or earn <= 0 or book <= 0 or divs < 0:
        raise ValueError("non-positive denominator or negative dividends")
    return {
        "pe": mc / earn,
        "pb": mc / book,
        "dividend_yield_pct": 100.0 * divs / mc,
    }


def month_reconstructable(rows, expected_members=50, min_weight_sum=0.985):
    """Strict gate for calling a historical month reconstructable.

    `rows` contains one row per constituent with keys:
      weight, pe, pb, dividend_yield_pct, filing_ok, dividend_history_ok.
    No neutral fill, imputation or cross-sectional scaling is allowed.
    """
    if len(rows) != int(expected_members):
        return False, f"member_count={len(rows)}"
    required = ("weight", "pe", "pb", "dividend_yield_pct")
    for r in rows:
        if not all(finite(r.get(k)) for k in required):
            return False, "missing_valuation_field"
        if not r.get("filing_ok", False):
            return False, "filing_not_point_in_time"
        if not r.get("dividend_history_ok", False):
            return False, "dividend_history_incomplete"
    total = sum(float(r["weight"]) for r in rows)
    if total > 2:
        total /= 100.0
    if total < float(min_weight_sum):
        return False, f"weight_sum={total:.6f}"
    return True, "complete"


def _session():
    s = requests.Session()
    s.headers.update(UA)
    # Best-effort cookie/bootstrap. Failure is reported by individual probes.
    for url in ("https://www.nseindia.com/", "https://www.niftyindices.com/"):
        try:
            s.get(url, timeout=12)
        except Exception:
            pass
    return s


def _get_json(session, url, params=None, timeout=18):
    r = session.get(url, params=params, timeout=timeout, headers={**UA, "Accept": "application/json,text/plain,*/*"})
    r.raise_for_status()
    return r.json()


def _parse_dates_from_record(record):
    out = []
    for k, v in (record or {}).items():
        if not isinstance(v, str):
            continue
        if "date" not in str(k).lower() and "time" not in str(k).lower():
            continue
        d = pd.to_datetime(v, errors="coerce", dayfirst=True)
        if not pd.isna(d):
            out.append((str(k), d))
    return out


def probe_financial_results(session, symbol):
    url = OFFICIAL_SOURCES["financial_results"]["api"]
    try:
        data = _get_json(session, url, {"index": "equities", "symbol": symbol, "period": "Quarterly"})
        records = data if isinstance(data, list) else (data.get("data") if isinstance(data, dict) else None)
        records = records if isinstance(records, list) else []
        dates = []
        consolidated_mentions = 0
        xbrl_links = 0
        for r in records:
            dates.extend(d for _, d in _parse_dates_from_record(r))
            text = " ".join(str(v) for v in r.values()).lower()
            consolidated_mentions += int("consolidated" in text)
            xbrl_links += sum("xbrl" in str(v).lower() for v in r.values())
        return {
            "symbol": symbol,
            "status": "ok",
            "records": len(records),
            "earliest_dated_record": str(min(dates).date()) if dates else None,
            "latest_dated_record": str(max(dates).date()) if dates else None,
            "records_mentioning_consolidated": consolidated_mentions,
            "xbrl_link_mentions": int(xbrl_links),
        }
    except Exception as e:
        return {"symbol": symbol, "status": "unavailable", "error": f"{type(e).__name__}: {e}"}


def probe_corporate_actions(session, symbol):
    url = OFFICIAL_SOURCES["corporate_actions"]["api"]
    try:
        data = _get_json(session, url, {"index": "equities", "symbol": symbol})
        records = data if isinstance(data, list) else (data.get("data") if isinstance(data, dict) else None)
        records = records if isinstance(records, list) else []
        dividend_rows = []
        dates = []
        for r in records:
            text = " ".join(str(v) for v in r.values()).lower()
            if "dividend" not in text:
                continue
            dividend_rows.append(r)
            for _, d in _parse_dates_from_record(r):
                dates.append(d)
        return {
            "symbol": symbol,
            "status": "ok",
            "records": len(records),
            "dividend_records": len(dividend_rows),
            "earliest_dividend_date_seen": str(min(dates).date()) if dates else None,
            "latest_dividend_date_seen": str(max(dates).date()) if dates else None,
        }
    except Exception as e:
        return {"symbol": symbol, "status": "unavailable", "error": f"{type(e).__name__}: {e}"}


def probe_weight_zip(session, month, url):
    try:
        r = session.get(url, timeout=20, headers={**UA, "Referer": "https://www.niftyindices.com/reports/monthly-reports"})
        r.raise_for_status()
        raw = r.content
        if not zipfile.is_zipfile(BytesIO(raw)):
            return {"month": month, "status": "not_zip", "http_status": r.status_code, "bytes": len(raw)}
        with zipfile.ZipFile(BytesIO(raw)) as z:
            names = z.namelist()
        return {
            "month": month,
            "status": "ok",
            "http_status": r.status_code,
            "bytes": len(raw),
            "files": names[:30],
            "file_count": len(names),
        }
    except Exception as e:
        return {"month": month, "status": "unavailable", "error": f"{type(e).__name__}: {e}"}


def fetch_current_constituent_count(session):
    url = "https://www.niftyindices.com/IndexConstituent/ind_nifty50list.csv"
    try:
        r = session.get(url, timeout=18, headers={**UA, "Referer": "https://www.niftyindices.com/indices/equity/broad-based-indices/NIFTY-50"})
        r.raise_for_status()
        q = pd.read_csv(StringIO(r.text.lstrip("\ufeff")))
        cols = {re.sub(r"[^a-z0-9]", "", str(c).lower()): c for c in q.columns}
        sc = next((cols[k] for k in ("symbol", "ticker") if k in cols), None)
        symbols = q[sc].dropna().astype(str).tolist() if sc else []
        return {"status": "ok", "rows": int(len(q)), "symbols_found": len(symbols), "sample": symbols[:10]}
    except Exception as e:
        return {"status": "unavailable", "error": f"{type(e).__name__}: {e}"}


def build():
    s = _session()
    financial = [probe_financial_results(s, x) for x in FINANCIAL_PROBE_SYMBOLS]
    actions = [probe_corporate_actions(s, x) for x in FINANCIAL_PROBE_SYMBOLS]
    weights = [probe_weight_zip(s, m, u) for m, u in WEIGHT_ARCHIVE_PROBES]
    current = fetch_current_constituent_count(s)

    fin_ok = [x for x in financial if x.get("status") == "ok"]
    act_ok = [x for x in actions if x.get("status") == "ok"]
    weight_ok = [x for x in weights if x.get("status") == "ok"]

    # Evidence classification deliberately separates "source exists" from
    # "machine probe worked in this CI run" and from "fully reconstructed".
    result = {
        "status": "complete",
        "generated_at": datetime.now(timezone.utc).replace(microsecond=0).isoformat(),
        "research_only": True,
        "live_model_changed": False,
        "live_allocation_changed": False,
        "target_definition": {
            "question": "Historical NIFTY 50 using actual historical index weights but today's accounting definitions, point-in-time only.",
            "counterfactual_free_float_since_2000": False,
            "accounting": METHODOLOGY["accounting_target"],
        },
        "official_sources": OFFICIAL_SOURCES,
        "historical_weight_evidence": {
            "verified_start": "2000-04",
            "verified_official_example": "NSE ISMR 2001 Annexure 4.2 publishes monthly constituent weights Apr-2000 through Jun-2001, with inclusion markers.",
            "later_archive": "Nifty Indices monthly reports expose market-capitalisation/weightage ZIP archives; representative URLs are probed below.",
            "key_implication": "Actual published index weights embed the weighting/IWF regime, so IWF need not be separately reconstructed for ratio aggregation.",
        },
        "machine_probes": {
            "current_constituents": current,
            "weight_archives": weights,
            "financial_results": financial,
            "corporate_actions": actions,
        },
        "probe_summary": {
            "financial_symbols_ok": len(fin_ok),
            "financial_symbols_total": len(financial),
            "corporate_action_symbols_ok": len(act_ok),
            "corporate_action_symbols_total": len(actions),
            "weight_archive_months_ok": len(weight_ok),
            "weight_archive_months_total": len(weights),
        },
        "reconstruction_gate": {
            "required_for_each_month": [
                "exact official constituent set and actual index weights",
                "TTM consolidated earnings known by signal date, standalone fallback only where consolidated unavailable",
                "latest eligible consolidated net worth known by signal date, standalone fallback only where consolidated unavailable",
                "rolling-12-month cash dividends using ex-dates known by signal date",
                "company market capitalisation / price-share basis consistent with the financial numerators",
                "corporate-action adjustment continuity",
                "all 50 constituent rows passing the point-in-time gate",
            ],
            "missing_value_policy": "fail closed; no neutral fill, interpolation, cross-sectional imputation or one-day methodology scaling",
            "earliest_fully_reconstructed_month": None,
            "reason": "This phase establishes source coverage and exact aggregation rules. No historical month is promoted until all 50 constituent accounting rows are independently assembled and validated.",
        },
        "next_validation_gate": {
            "pilot_period": "2023-09 onward",
            "test": "Reconstruct index PE/PB/DY from constituent rows and actual weights, then compare against published NIFTY ratios under the same current definitions.",
            "promotion_condition": "Only extend backward after the recent pilot reproduces published ratios within a pre-declared tolerance and all rows are point-in-time clean.",
        },
        "interpretation": (
            "Official weight history is no longer the principal conceptual blocker: NSE publications demonstrate monthly constituent weights from Apr-2000. "
            "The harder remaining task is complete point-in-time company accounting history under today's definitions, especially before modern XBRL filing coverage."
        ),
    }
    OUT.write_text(json.dumps(result, indent=2, allow_nan=False), encoding="utf-8")
    print(json.dumps({
        "status": result["status"],
        "weight_history_verified_start": result["historical_weight_evidence"]["verified_start"],
        **result["probe_summary"],
        "earliest_fully_reconstructed_month": None,
        "live_model_changed": False,
    }, separators=(",", ":")))
    return result


if __name__ == "__main__":
    build()

pipeline_sources.scripts/domestic_macro.py:
"""India domestic macro block for Anup Nifty Valuation V3.6.

Current CPI and IIP are sourced from official Government of India PIB releases
issued by MoSPI/NSO. The adapter discovers newer releases from PIB's current-
month All Releases page, while retaining the last verified release URL from the
previous successful model run. This avoids hard-coding the data values and also
avoids depending on the currently unstable authenticated eSankhyiki API.

Scores use explicit economic anchors:
- CPI vs RBI's 4% inflation target
- IIP growth vs a 5% medium-growth anchor
- real policy repo rate vs a 1% reference
"""
from __future__ import annotations
from datetime import date
from urllib.parse import urljoin
import math,re
import numpy as np
import pandas as pd
from lxml import html
import http_client as requests

UA={'User-Agent':'Mozilla/5.0 (compatible; AnupNiftyValuation/3.6; personal research)'}
RBI='https://www.rbi.org.in/'
PIB_ALL='https://www.pib.gov.in/AllRelease.aspx?MenuId=22&PMO=1&lang=1&reg=1'
PIB_BASE='https://www.pib.gov.in/'
# Bootstrap URLs are official release pages, not hard-coded economic values.
# Thereafter the prior successful source URL is carried forward automatically
# until PIB publishes a newer matching release in the current month.
PIB_SEED={
    'cpi':'https://www.pib.gov.in/PressReleasePage.aspx?PRID=2298247',
    'iip':'https://www.pib.gov.in/PressReleasePage.aspx?PRID=2304222',
}


def finite(x):
    try:return x is not None and math.isfinite(float(x))
    except (TypeError,ValueError):return False

def fresh(asof,max_age):
    try:
        age=(date.today()-date.fromisoformat(str(asof)[:10])).days
        return 0<=age<=max_age
    except (TypeError,ValueError):return False

def period_end(month,year):
    if isinstance(month,(int,float,np.integer,np.floating)) or str(month).strip().isdigit():mm=int(float(month))
    else:mm=pd.to_datetime(str(month).strip(),format='%B').month
    return pd.Period(f'{int(year):04d}-{mm:02d}',freq='M').end_time.date().isoformat()
def clean_text(text):
    try:return ' '.join(html.fromstring(str(text)).text_content().split())
    except Exception:return ' '.join(str(text).split())
def _dedupe(xs):
    seen=set();out=[]
    for x in xs:
        if x and x not in seen:seen.add(x);out.append(x)
    return out

def parse_cpi(text,source_url=None):
    page=clean_text(text)
    pats=[
      r'Retail inflation based on Consumer Price Index in\s+([A-Za-z]+),?\s+(\d{4})\s+is\s+(-?\d+(?:\.\d+)?)\s*%',
      r'Year[- ]on[- ]year inflation rate based on All India Consumer Price Index.*?(?:month of|for)\s+([A-Za-z]+),?\s+(\d{4}).{0,320}?(?:is|stood at|estimated at)\s+(-?\d+(?:\.\d+)?)\s*%',
      r'CONSUMER PRICE INDEX.*?FOR\s+([A-Za-z]+),?\s+(\d{4}).{0,500}?inflation.{0,120}?(-?\d+(?:\.\d+)?)\s*%',
    ]
    match=None
    for p in pats:
        match=re.search(p,page,re.I)
        if match:break
    if not match:raise RuntimeError('All-India CPI inflation not parsed from official PIB release')
    month,year,value=match.groups();value=float(value)
    if not -5<value<30:raise RuntimeError('CPI inflation outside validation range')
    asof=period_end(month,year)
    return {'value':value,'asof':asof,'source_url':source_url,'status':'live' if fresh(asof,75) else 'stale','label':'All-India CPI inflation, YoY','source':'MoSPI/NSO via PIB'}

def parse_iip(text,source_url=None):
    page=clean_text(text)
    pats=[
      r'IIP growth rate for the month of\s+([A-Za-z]+)\s+(\d{4})\s+is\s+(-?\d+(?:\.\d+)?)\s*(?:percent|%)',
      r'Index of Industrial Production.*?(?:recorded|records|growth of|grew by).{0,80}?(-?\d+(?:\.\d+)?)\s*%.*?(?:in|during)\s+([A-Za-z]+)\s+(\d{4})',
    ]
    m=re.search(pats[0],page,re.I)
    if m:month,year,value=m.groups()
    else:
        m=re.search(pats[1],page,re.I)
        if not m:raise RuntimeError('India IIP growth not parsed from official PIB release')
        value,month,year=m.groups()
    value=float(value)
    if not -30<value<40:raise RuntimeError('IIP growth outside validation range')
    asof=period_end(month,year)
    return {'value':value,'asof':asof,'source_url':source_url,'status':'live' if fresh(asof,90) else 'stale','label':'India IIP growth, YoY','source':'MoSPI/NSO via PIB'}

def parse_repo(text,source_url=RBI):
    page=clean_text(text)
    section=re.search(r'Policy\s+Rates(.*?)(?:Reserve\s+Ratios|Exchange\s+Rates)',page,re.I);target=section.group(1) if section else page
    m=re.search(r'Policy\s+Repo\s+Rate\s*:?\s*(\d+(?:\.\d+)?)\s*%',target,re.I)
    if not m:raise RuntimeError('RBI policy repo rate not parsed')
    value=float(m.group(1))
    if not 1<value<15:raise RuntimeError('Repo rate outside validation range')
    return {'value':value,'asof':date.today().isoformat(),'source_url':source_url,'status':'live','label':'RBI policy repo rate','date_basis':'retrieval date; current policy rate remains effective until changed'}

def _link_matches(kind,text):
    s=' '.join(str(text).lower().split())
    if kind=='cpi':
        return ('consumer price index' in s or re.search(r'\bcpi\b',s)) and any(k in s for k in ('press release','inflation','consumer price index'))
    return ('industrial production' in s or re.search(r'\biip\b',s)) and any(k in s for k in ('quick estimate','growth','industrial production','iip'))

def pib_links_from_html(kind,text):
    """Extract candidate official release links from PIB's current-month page."""
    tree=html.fromstring(text);out=[]
    for a in tree.xpath('//a[@href]'):
        href=urljoin(PIB_BASE,a.get('href') or '')
        own=' '.join(a.text_content().split())
        parent=' '.join(a.getparent().text_content().split()) if a.getparent() is not None else ''
        context=f'{own} {parent}'
        if _link_matches(kind,context) and any(k.lower() in href.lower() for k in ('pressrelease','pressrelese','erelcontent')):
            out.append(href)
    return _dedupe(out)

def discover_pib_links(kind):
    try:
        r=requests.get(PIB_ALL,headers=UA,timeout=25);r.raise_for_status();return pib_links_from_html(kind,r.text)
    except Exception:return []

def _prior_source(prior,kind):
    try:
        key='india_cpi_yoy' if kind=='cpi' else 'india_iip_yoy'
        return (((prior or {}).get('factors') or {}).get(key) or {}).get('source_url')
    except Exception:return None

def fetch_release(kind,parser,prior=None):
    """Fetch newest parseable official release without inventing missing data."""
    candidates=_dedupe(discover_pib_links(kind)+[_prior_source(prior,kind),PIB_SEED[kind]])
    parsed=[];errors=[]
    for url in candidates:
        try:
            r=requests.get(url,headers=UA,timeout=25);r.raise_for_status();x=parser(r.text,url)
            parsed.append(x)
        except Exception as e:errors.append(f'{url}: {type(e).__name__}: {e}')
    if not parsed:raise RuntimeError(f'No parseable official PIB {kind.upper()} release; ' + ' | '.join(errors[-3:]))
    return max(parsed,key=lambda x:x['asof'])

def fetch_repo():
    r=requests.get(RBI,headers=UA,timeout=25);r.raise_for_status();return parse_repo(r.text,RBI)

def build(prior=None):
    cpi=fetch_release('cpi',parse_cpi,prior);iip=fetch_release('iip',parse_iip,prior);repo=fetch_repo()
    if any(x.get('status')!='live' or not finite(x.get('value')) for x in (cpi,iip,repo)):
        raise RuntimeError('India domestic macro source is stale or unavailable')
    inflation_gap=float(cpi['value'])-4.0;real_repo=float(repo['value'])-float(cpi['value'])
    inflation_score=float(np.tanh(-inflation_gap/1.5))
    activity_score=float(np.tanh((float(iip['value'])-5.0)/4.0))
    policy_score=float(np.tanh(-(real_repo-1.0)/1.5))
    score=.40*inflation_score+.35*activity_score+.25*policy_score
    factors={
      'india_cpi_yoy':dict(cpi,score=inflation_score,reference=4.0,reference_label='RBI inflation target'),
      'india_iip_yoy':dict(iip,score=activity_score,reference=5.0,reference_label='medium-growth anchor'),
      'india_repo_rate':dict(repo,score=policy_score,real_repo=real_repo,reference_real_rate=1.0,reference_label='real policy-rate anchor')
    }
    return {'score':float(score),'coverage':1.0,'status':'live','factors':factors,'inflation_gap_pp':inflation_gap,'real_repo_rate':real_repo,'method':'economic-anchor-v1','source_policy':'official-PIB-discovery-with-prior-release-carry-forward'}

